    std::uint8_t *aWindLaneC = pWorkSpace->mWindLaneC;
    std::uint8_t *aWindLaneD = pWorkSpace->mWindLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xE2CF5E0A0B81D9D7ULL + 0xF4BED3EDC7C1F805ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0xC1BBC9AB87EBAC5FULL + 0xDC6217B1F2E74628ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0x9971DD5FDCF4BD25ULL + 0x9DACBA50CB481989ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseB(pNonce * 0xEE1C7A32A0E76703ULL + 0xD386F85F61AACE46ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseA(pNonce * 0xE11455F49DA1E787ULL + 0xD3525C19975845B8ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseC(pNonce * 0x94A2D1E8A0752DB1ULL + 0xAABA2E98FB853ADEULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseA(pNonce * 0xD37D6B7F6799E50BULL + 0xCA16796926F1CF06ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordH = TwistMix64::DiffuseA(pNonce * 0xD4D14897E5F974CBULL + 0xA133B85EA5C8CDC9ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseC(pNonce * 0xFC4669BE0E6CD20DULL + 0xBE0C1CC1BF4A6AB4ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordJ = TwistMix64::DiffuseA(pNonce * 0x8DDFE6FEBB2D326DULL + 0xDBE4B4F14C1F5FF0ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseA(pNonce * 0xE649F5217010A6E5ULL + 0x9BC1C82106F4105FULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseB(pNonce * 0xE39D50BD13CE2AD3ULL + 0x9BAFD077C92F7CACULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseA(pNonce * 0xC106C2C448F9C283ULL + 0x8B98F808C3EBC1C3ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseA(pNonce * 0xDA0701293105DC59ULL + 0x82C241CAAFCC67D2ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordO = TwistMix64::DiffuseC(pNonce * 0xD9A771218772008BULL + 0x97F6F56B0E3B4568ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordP = TwistMix64::DiffuseB(pNonce * 0xD553041EA268F755ULL + 0xD934C1E3A3626CBEULL);
    std::uint64_t aDomainWordIngress = pConstants->mIngress;
