    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSource;
    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xC7B8E88F03CA021FULL + 0xAB59B4481C7DC450ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0xE6C284E48A4B2D2FULL + 0x85406D1685E681A0ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseB(pNonce * 0xC1A3CF7A07497F5FULL + 0xCDC913E9205D5E50ULL);
