            aCross = (RotL64(aWaterLaneC[((S_BLOCK1 - aIndex + 2735U)) & S_BLOCK1], 47U) ^ RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 1048U)) & S_BLOCK1], 19U));
