            aOrbiterA = ((aWandererA + RotL64(aScatter, 19U)) + RotL64(aCarry, 43U)) + 0x65B040FCB48A0DFBULL;
            aOrbiterJ = (aWandererB + RotL64(aCross, 5U)) + 0x2E0F7A5C82E5C57EULL;
            aOrbiterG = (aWandererC + RotL64(aIngress, 57U)) + 0xB7EBB69C38920569ULL;
            aOrbiterI = (aWandererJ + RotL64(aPrevious, 24U)) + 0xC3A77B96B7DC8A59ULL;
            aOrbiterE = ((aWandererI + RotL64(aScatter, 35U)) + 0x333224F7279CD4EAULL) + aTwistOrbiterAssignSaltA[((aIndex + 18U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aCross, 53U)) + RotL64(aCarry, 21U)) + 0xC532598166C54F8BULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x2A8353E312C844CAULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0xEF07E9AC71A7387BULL;
            aOrbiterB = RotL64((aOrbiterB * 0x45967B6116CE7937ULL), 11U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0x1F81162BC4FB9816ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0x11F11C588D895ED6ULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x6F86A064F2B128A7ULL), 5U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0x76909754348C9656ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterI) ^ 0x656BAF14B447357CULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x2A65F3E9D4AF9161ULL), 47U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0xCF8498E6A9F2DBDDULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterG) ^ 0x6A63EE10BB41E4D4ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 7U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xAD5B996E76FD79DFULL), 43U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0xE9A6FC3540B760DDULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0x3D1421CECE6597ECULL;
            aOrbiterI = RotL64((aOrbiterI * 0x5060209E0363106FULL), 29U);
