            aScatter = (RotL64(aIngress, 53U) ^ RotL64(aCarry, 5U)) + (RotL64(aCross, 21U) + RotL64(aPrevious, 34U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterG = ((aWandererC + RotL64(aScatter, 51U)) + 0x63BF5E093C36F14CULL) + aTwistOrbiterAssignSaltD[((aIndex + 17U)) & S_SALT1];
            aOrbiterJ = (aWandererB + RotL64(aPrevious, 22U)) + 0x0C6623AE02DF8C46ULL;
            aOrbiterK = (((aWandererG + RotL64(aCross, 3U)) + RotL64(aCarry, 57U)) + 0x7DB9B7664B5F94EDULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
