            //
            aScatter = (RotL64(aIngress, 54U) + RotL64(aCarry, 5U)) ^ (RotL64(aCross, 39U) ^ RotL64(aPrevious, 19U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterF = (aWandererG + RotL64(aPrevious, 53U)) + 0x741C4502E9054BEFULL;
            aOrbiterJ = (aWandererJ + RotL64(aIngress, 19U)) + 0x24995EDBF4CEF80EULL;
            aOrbiterC = ((aWandererA + RotL64(aScatter, 29U)) + RotL64(aCarry, 57U)) + 0xF61082D50ED0DDD2ULL;
            aOrbiterE = ((aWandererE + RotL64(aCross, 24U)) + RotL64(aCarry, 23U)) + 0x13B6EAD89DC98094ULL;
            aOrbiterH = ((aWandererF + RotL64(aPrevious, 57U)) + RotL64(aCarry, 39U)) + 0x4DA103CB8A93DDC3ULL;
            aOrbiterA = ((aWandererK + RotL64(aIngress, 39U)) + 0x56DDE8132701EB38ULL) + aTwistOrbiterAssignSaltF[((aIndex + 9U)) & S_SALT1];
            aOrbiterK = (aWandererC + RotL64(aScatter, 35U)) + 0x0854EEE41BB40996ULL;
            aOrbiterD = (aWandererI + RotL64(aCross, 5U)) + 0x086736F15305D0BEULL;
            aOrbiterG = ((aWandererD + RotL64(aPrevious, 48U)) + 0xC385587691D098ABULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 10U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x83503A77C0672DEAULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0x05E9B1EF2CCB0377ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x3EFAA2024B539E4BULL), 53U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0x305C3284F7973D8FULL) + aTwistOrbiterUpdateSaltE[((aIndex + 21U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0x7D2A7A9AAB20E4A0ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x33C6623309E474E9ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterA) + 0x11A691225D420DB7ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x5DA7ACB4B1575EDFULL;
            aOrbiterK = RotL64((aOrbiterK * 0xF4C9B3C873C87AFDULL), 3U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0x82950E97BE30971DULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterK) ^ 0xEA2FD650F3CB9D60ULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xF392CE53F6E10A53ULL), 47U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0xC334A2F4B3A8C712ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x72452A5BA04AE263ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xBE22775EA81A8983ULL), 39U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterE) + 0x8D4BC5FC3533715EULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x548E679FC2D355C7ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xB04E71C91FAB438BULL), 13U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0x8AFBCB8203199E85ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x8C255F777CF57678ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xBC9E023B405BA47BULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x34C9E760239FDA8CULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0xB8A21A732596D48BULL;
            aOrbiterG = RotL64((aOrbiterG * 0x9D11D8835F1D61DFULL), 19U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x9B0A13B6564AA3F4ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterA) ^ 0xE774DB460EE510CCULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xB872166E83790B79ULL), 43U);
