            aIngress = aIngress + (RotL64(aOrbiterC, 22U) ^ aOrbiterE);
            aIngress = aIngress + (aOrbiterH ^ RotL64(aOrbiterF, 5U));
            aIngress = aIngress + RotL64(aOrbiterA, 37U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererA = aWandererA + (((RotL64(aIngress, 29U) + RotL64(aOrbiterC, 58U)) + aOrbiterF) + RotL64(aCarry, 39U));
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 48U) + aOrbiterD) + RotL64(aOrbiterK, 19U));
