            aWandererC = aWandererC ^ ((RotL64(aCross, 5U) + RotL64(aOrbiterG, 5U)) + aOrbiterF);
            aWandererG = aWandererG + ((RotL64(aIngress, 11U) + aOrbiterJ) + RotL64(aOrbiterE, 23U));
            aWandererI = aWandererI ^ (((RotL64(aCross, 39U) + RotL64(aOrbiterH, 36U)) + aOrbiterF) + aTwistWandererUpdateSaltA[(((31U - aIndex) + 5U)) & S_SALT1]);
            aWandererE = aWandererE + ((((RotL64(aScatter, 34U) + aOrbiterG) + RotL64(aOrbiterK, 51U)) + RotL64(aCarry, 29U)) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 22U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aPrevious, 23U) + aOrbiterE) + RotL64(aOrbiterH, 11U));
            aWandererK = aWandererK + ((RotL64(aIngress, 53U) + aOrbiterA) + RotL64(aOrbiterE, 41U));
