            aOrbiterD = (aWandererA + RotL64(aIngress, 39U)) + 0x1D83751B1B5DD44DULL;
            aOrbiterA = (aWandererJ + RotL64(aScatter, 5U)) + 0x1E9019624F60B5B5ULL;
            aOrbiterJ = ((aWandererG + RotL64(aCross, 13U)) + RotL64(aCarry, 35U)) + 0x6821E07405E05045ULL;
            aOrbiterB = ((aWandererH + RotL64(aIngress, 23U)) + RotL64(aCarry, 13U)) + 0x4CAF93E0E1A9580EULL;
            aOrbiterH = ((aWandererI + RotL64(aPrevious, 43U)) + 0xEEF7C7D8F418F7C6ULL) + aKeyRotateAOrbiterAssignSaltD[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterE = ((aWandererC + RotL64(aCross, 50U)) + 0xCB50DD36C8CA8FDBULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 9U)) & S_SALT1];
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x5922EC8D160F3A4CULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x0B3E1B55776ABCCDULL;
