            aWandererG = aWandererG ^ ((RotL64(aScatter, 47U) + RotL64(aOrbiterE, 28U)) + aOrbiterD);
            aWandererE = aWandererE + (((RotL64(aPrevious, 23U) + aOrbiterI) + RotL64(aOrbiterJ, 3U)) + RotL64(aCarry, 29U));
