            aOrbiterI = ((aWandererI + RotL64(aScatter, 37U)) + 0x9C698581F44CC44EULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 4U)) & S_SALT1];
            aOrbiterK = ((aWandererD + RotL64(aPrevious, 39U)) + 0xE981AEB848175E13ULL) + aKeyRotateAOrbiterAssignSaltD[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterD = ((aWandererF + RotL64(aCross, 47U)) + RotL64(aCarry, 37U)) + 0x93865842472A1612ULL;
