            aCross ^= (RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 7606U)) & S_BLOCK1], 29U) ^ RotL64(aPoisonLaneC[((aIndex + 1204U)) & S_BLOCK1], 5U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 27U) ^ RotL64(aCross, 39U)) + (RotL64(aPrevious, 60U) ^ RotL64(aCarry, 11U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterC = (aWandererA + RotL64(aIngress, 43U)) + 0x84E8587E603D8A1EULL;
            aOrbiterF = ((aWandererG + RotL64(aPrevious, 37U)) + 0xB8DE03C41A3473A9ULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 28U)) & S_SALT1];
            aOrbiterE = ((aWandererF + RotL64(aCross, 21U)) + RotL64(aCarry, 27U)) + 0x5EB580A6AFCB3E50ULL;
            aOrbiterI = ((aWandererB + RotL64(aScatter, 11U)) + RotL64(aCarry, 5U)) + 0x4F54D3C1589B20C1ULL;
            aOrbiterJ = (aWandererD + RotL64(aCross, 30U)) + 0x655B18A84DE8E19BULL;
            aOrbiterH = ((aWandererC + RotL64(aIngress, 3U)) + RotL64(aCarry, 43U)) + 0xB5E0AA686F96E284ULL;
            aOrbiterD = ((aWandererK + RotL64(aScatter, 57U)) + 0xF45BC14EC5FD2C14ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 26U)) & S_SALT1];
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x324F8497EA78CD77ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0xF9A9BBAF1DE0DE05ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1856BF3AC0FD240DULL), 13U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0x3196C7EB87203103ULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0xBC8E0A773463E68BULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x854EE5E5B27CEC5DULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0x0661D932E5520625ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x7DEEE87C4633A55EULL;
            aOrbiterD = RotL64((aOrbiterD * 0xFC6AAD466D74A585ULL), 35U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterJ) + 0xC2B9613A503EC808ULL) + aKeyRotateAOrbiterUpdateSaltA[((aIndex + 3U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x259CA41587744BE9ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x32BAD430F8D62783ULL), 51U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0x02CD98841FB8A9B9ULL) + aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0xCAB784B454C11EF0ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x09F5BE1D5F5CD5D9ULL), 43U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x3D4B5BDC3F5297D8ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0x1BBE1AF4F68C6CA5ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x71E8E1BC3F66426FULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xE19D346B30FE64A5ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterI) ^ 0xBB1B4B1AA9208A0BULL) ^ aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xCEC828FAE15D5913ULL), 21U);
            //
            aIngress = RotL64(aOrbiterJ, 29U) ^ aOrbiterI;
            aIngress = aIngress + (RotL64(aOrbiterF, 35U) ^ aOrbiterD);
            aIngress = aIngress + (RotL64(aOrbiterH, 47U) ^ aOrbiterE);
            aIngress = aIngress + RotL64(aOrbiterC, 57U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererK = aWandererK + ((((RotL64(aPrevious, 19U) + aOrbiterF) + RotL64(aOrbiterC, 35U)) + RotL64(aCarry, 47U)) + aKeyRotateAWandererUpdateSaltE[(((31U - aIndex) + 23U)) & S_SALT1]);
            aWandererB = aWandererB ^ (((RotL64(aScatter, 39U) + RotL64(aOrbiterI, 27U)) + aOrbiterC) + aKeyRotateAWandererUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1]);
            aWandererC = aWandererC + ((RotL64(aCross, 13U) + aOrbiterH) + RotL64(aOrbiterD, 43U));
            aWandererG = aWandererG ^ ((RotL64(aIngress, 47U) + RotL64(aOrbiterC, 60U)) + aOrbiterE);
            aWandererD = aWandererD + (((RotL64(aCross, 27U) + RotL64(aOrbiterE, 19U)) + aOrbiterJ) + RotL64(aCarry, 29U));
