        //
        // Ingress:
        //      aFuseLaneA (-->), aWindLaneC (-->), aShadowLaneA (-->), aPoisonLaneA (<-?->)
        //
        // Cross:
        //      aWindLaneA (<--), aWindLaneD (<--), aLightningLaneC (<--), aPlasmaLaneD (<-?->)
        //
        // Destination:
        //      aFuseLaneB
