            aPrevious = aIngress;
            //
            aIngress = (RotL64(aFuseLaneA[((aIndex + 16006U)) & S_BLOCK1], 57U) ^ RotL64(aWindLaneC[((aIndex + 13706U)) & S_BLOCK1], 11U));
            aIngress ^= (RotL64(aShadowLaneA[((aIndex + 8381U)) & S_BLOCK1], 43U) ^ RotL64(aPoisonLaneA[((aIndex + 12074U)) & S_BLOCK1], 28U));
            aIngress = TwistMix64::DiffuseA((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 14973U)) & S_BLOCK1], 29U) ^ RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 15704U)) & S_BLOCK1], 38U));
            aCross ^= (RotL64(aLightningLaneC[((S_BLOCK1 - aIndex + 10222U)) & S_BLOCK1], 3U) ^ RotL64(aPlasmaLaneD[((S_BLOCK1 - aIndex + 9030U)) & S_BLOCK1], 11U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCarry, 5U) + RotL64(aPrevious, 41U)) + (RotL64(aIngress, 53U) ^ RotL64(aCross, 28U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterK = (aWandererH + RotL64(aScatter, 60U)) + 0x54DA6B6E9C7C27A3ULL;
            aOrbiterF = ((aWandererD + RotL64(aCross, 47U)) + RotL64(aCarry, 23U)) + 0x493A2A797EBDF298ULL;
            aOrbiterH = ((aWandererJ + RotL64(aIngress, 37U)) + RotL64(aCarry, 3U)) + 0xA0A73102022B4A6EULL;
            aOrbiterA = ((aWandererB + RotL64(aPrevious, 13U)) + RotL64(aCarry, 53U)) + 0x6A6ACBE40916853DULL;
            aOrbiterC = (aWandererC + RotL64(aIngress, 19U)) + 0x9DF256657753425AULL;
            aOrbiterE = ((aWandererI + RotL64(aScatter, 3U)) + 0x8ED3908E0CD03648ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 7U)) & S_SALT1];
            aOrbiterB = ((aWandererF + RotL64(aCross, 27U)) + 0x6417216648308B4CULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 3U)) & S_SALT1];
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x0CE60FA253A8250EULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterK) ^ 0xDC53889A543E2CC5ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x998558F4C7B1EFB7ULL), 5U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterC) + 0xB5CD1DE20B4B7EB4ULL) + aKeyRotateAOrbiterUpdateSaltC[((aIndex + 17U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x4ED066286F6BBDECULL;
            aOrbiterF = RotL64((aOrbiterF * 0x56B98A62D7A2FDE7ULL), 43U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xD9653C53D95111ADULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x723F1A28F91617DFULL;
            aOrbiterE = RotL64((aOrbiterE * 0x025E42DCFDBC4605ULL), 35U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x972EC582FA8FAC91ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterE) ^ 0xAD75D5124F037691ULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x2C0FE12F5E5C4D8BULL), 57U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0xF6C6A534B2EF927EULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterH) ^ 0x8BAAB169EF1B1FDEULL) ^ aKeyRotateAOrbiterUpdateSaltB[((aIndex + 8U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x20CB8D05AB51C7A3ULL), 11U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x8B9D61A574141EACULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x07C4DD29624F8FDAULL;
            aOrbiterB = RotL64((aOrbiterB * 0x826D524BD6FC3283ULL), 51U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x49DD9C5F82E480D3ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0xE3B3532448F9FC14ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x0B72BBE8F9158B49ULL), 29U);
            //
